   784  static inline void
   785  hb_ot_position (hb_ot_shape_context_t *c)
   786  {
   787    c->buffer->clear_positions ();
   788
   789    hb_ot_position_default (c);
   790
   791    hb_ot_position_complex (c);
   792
   793    if (c->fallback_positioning && c->plan->shaper->fallback_position)
   794      _hb_ot_shape_fallback_position (c->plan, c->font, c->buffer);
   795
   796    if (HB_DIRECTION_IS_BACKWARD (c->buffer->props.direction))
   797      hb_buffer_reverse (c->buffer);
   798
   799    /* Visual fallback goes here. */
   800
   801    if (c->fallback_positioning)
   802      _hb_ot_shape_fallback_kern (c->plan, c->font, c->buffer);
   803
   804    _hb_buffer_deallocate_gsubgpos_vars (c->buffer);
   805
   806    //hb_aat_layout_position (c->font, c->buffer);
